<?php $pageTitle='Find Doctor';require __DIR__.'/header.php';?><div class="head"><h1>Find a Doctor</h1></div><form class="filters" method="get"><input type="hidden" name="action" value="doctors"><input name="name" placeholder="Doctor name" value="<?=htmlspecialchars($_GET['name']??'')?>"><select name="department"><option value="">All Departments</option><?php foreach($departments as $d):?><option value="<?=$d['id']?>" <?=($_GET['department']??'')==$d['id']?'selected':''?>><?=htmlspecialchars($d['name'])?></option><?php endforeach;?></select><button class="btn primary">Search</button></form><div class="doctors"><?php foreach($doctors as $d):?><article class="card"><div class="avatar"><?=strtoupper($d['name'][0])?></div><h2>Dr. <?=htmlspecialchars($d['name'])?></h2><b><?=$d['specialization']?></b><p><?=$d['department_name']?></p><p>Fee: ৳<?=number_format($d['fee'],2)?></p><p>Visiting: <?=htmlspecialchars($d['available_days'])?><br><?=date('g:i A',strtotime($d['start_time']))?>–<?=date('g:i A',strtotime($d['end_time']))?> · Room <?=$d['room']?></p><a class="btn primary full" href="index.php?action=book&doctor_id=<?=$d['id']?>">Book Appointment</a></article><?php endforeach;?></div><?php require __DIR__.'/footer.php';?>